cat >> tests/deliver_test.sh.new <<'EOF'
#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
# ADR-0009: 4 attempts, waits 3^i seconds (3, 9, 27); the count comes from RELAY_ATTEMPTS (runbook).
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "deliver default plan"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "deliver RELAY_ATTEMPTS"; fail=1; }
[ "$(RELAY_RETRY_MAX=6 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "deliver RELAY_RETRY_MAX ignored"; fail=1; }
exit $fail
EOF
